@keyframes chart-36-rise { from { transform: scaleY(0); } }
@keyframes chart-36-draw { from { clip-path: inset(0 100% 0 0); } }
@keyframes chart-36-land { from { opacity: 0; transform: scale(0.6); } }
@keyframes chart-36-fade { from { opacity: 0; } }
[data-chart-36-rise] { animation: chart-36-rise 420ms cubic-bezier(0.23, 1, 0.32, 1) var(--chart-36-delay, 0ms) backwards; }
[data-chart-36-draw] { animation: chart-36-draw 640ms cubic-bezier(0.77, 0, 0.175, 1) 120ms backwards; }
[data-chart-36-land] { animation: chart-36-land 200ms cubic-bezier(0.23, 1, 0.32, 1) 680ms backwards; transform-box: fill-box; transform-origin: center; }
[data-chart-36-fade] { animation: chart-36-fade 240ms cubic-bezier(0.23, 1, 0.32, 1) 200ms backwards; }
@media (prefers-reduced-motion: reduce) {
  :is([data-chart-36-rise], [data-chart-36-draw], [data-chart-36-land], [data-chart-36-fade]) { animation: chart-36-fade 200ms cubic-bezier(0.23, 1, 0.32, 1) backwards; }
}
[data-chart-36-settled] :is([data-chart-36-rise], [data-chart-36-draw], [data-chart-36-land], [data-chart-36-fade]) { animation: none; }
[data-chart-36-reading] [data-chart-36-col]:not([data-chart-36-lit]) { opacity: 0.3; }
:is([data-chart-36-band], [data-chart-36-dot]):not([data-chart-36-lit]) { opacity: 0; }

